{
  "name": "flow-engine-pager-{{stamp}}",
  "description": "Fetches one page and emits an item per record. Empty when the pages run out.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "p1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "p2",
      "type": "openconnector.source-call",
      "config": {
        "method": "GET",
        "source": "{{extSource}}",
        "endpoint": "/posts?_limit=10&_page={{ iteration.index }}"
      }
    },
    {
      "id": "p3",
      "type": "openregister.explode",
      "config": {
        "path": "response.body",
        "as": "item",
        "keepRecord": false
      }
    },
    {
      "id": "p4",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "p1",
      "to": "p2"
    },
    {
      "id": "b",
      "from": "p2",
      "to": "p3"
    },
    {
      "id": "c",
      "from": "p3",
      "to": "p4"
    }
  ]
}

{
  "name": "flow-engine-sync-{{stamp}}",
  "description": "Upserts one page of records. Called once per page by the paginated sync.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "s1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "s2",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "upsert",
        "match": {
          "externalId": "{{ item.id }}"
        },
        "fields": {
          "name": "{{ item.title }}",
          "externalId": "{{ item.id }}",
          "status": "paged"
        }
      }
    },
    {
      "id": "s3",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "s1",
      "to": "s2"
    },
    {
      "id": "b",
      "from": "s2",
      "to": "s3"
    }
  ]
}

{
  "name": "flow-engine-api-sync-{{stamp}}",
  "description": "Fetch a collection from an external API and write each item as a local object.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "call1",
      "type": "openconnector.source-call",
      "config": {
        "method": "GET",
        "source": "{{extSource}}",
        "endpoint": "/users"
      }
    },
    {
      "id": "x1",
      "type": "openregister.explode",
      "config": {
        "path": "response.body",
        "as": "item",
        "keepRecord": false
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "create",
        "fields": {
          "name": "{{ item.name }}",
          "sourceId": "{{ item.username }}",
          "status": "synced"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "call1"
    },
    {
      "id": "b",
      "from": "call1",
      "to": "x1"
    },
    {
      "id": "c",
      "from": "x1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-notify-on-change-{{stamp}}",
  "description": "Read a synced object, move it to reviewed, and raise a Nextcloud notification.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "r1",
      "type": "openregister.object-read",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "filters": {
          "status": "synced"
        },
        "limit": 1,
        "fanOut": true
      }
    },
    {
      "id": "s1",
      "type": "openregister.set-fields",
      "config": {
        "set": {
          "status": "reviewed"
        }
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "update",
        "match": [
          {
            "property": "sourceId",
            "value": "{{ sourceId }}"
          }
        ],
        "fields": {
          "status": "reviewed"
        }
      }
    },
    {
      "id": "n1",
      "type": "openconnector.source-call",
      "config": {
        "method": "POST",
        "source": "{{ncSource}}",
        "endpoint": "/ocs/v2.php/apps/notifications/api/v2/admin_notifications/admin",
        "body": {
          "shortMessage": "Flow engine test: an object was reviewed"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "r1"
    },
    {
      "id": "b",
      "from": "r1",
      "to": "s1"
    },
    {
      "id": "c",
      "from": "s1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "n1"
    },
    {
      "id": "e",
      "from": "n1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-mailbox-summary-ai-{{stamp}}",
  "description": "Fetch messages, hand them to an agent for a one-line summary, store the result.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "call1",
      "type": "openconnector.source-call",
      "config": {
        "method": "GET",
        "source": "{{extSource}}",
        "endpoint": "/posts?_limit=3"
      }
    },
    {
      "id": "a1",
      "type": "hermiq.agent-step",
      "config": {
        "agent": "{{agent}}",
        "prompt": "Summarise these messages in one short sentence."
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "create",
        "fields": {
          "name": "mailbox-summary",
          "status": "summarised"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "call1"
    },
    {
      "id": "b",
      "from": "call1",
      "to": "a1"
    },
    {
      "id": "c",
      "from": "a1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-data-quality-sweep-{{stamp}}",
  "description": "Walk the register on a schedule and flag every record that fails a rule.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-schedule",
      "config": {
        "cron": "0 3 * * *"
      }
    },
    {
      "id": "r1",
      "type": "openregister.object-read",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "limit": 100,
        "fanOut": true
      }
    },
    {
      "id": "f1",
      "type": "openregister.filter",
      "config": {
        "condition": {
          "==": [
            {
              "var": "json.status"
            },
            "synced"
          ]
        }
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "create",
        "fields": {
          "name": "quality-finding",
          "status": "flagged",
          "sourceId": "{{ sourceId }}"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "r1"
    },
    {
      "id": "b",
      "from": "r1",
      "to": "f1"
    },
    {
      "id": "c",
      "from": "f1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-enrichment-{{stamp}}",
  "description": "Look a record up in an external source and store the derived field.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "call1",
      "type": "openconnector.source-call",
      "config": {
        "method": "GET",
        "source": "{{extSource}}",
        "endpoint": "/users/1"
      }
    },
    {
      "id": "m1",
      "type": "openregister.set-fields",
      "config": {
        "set": {
          "note": "{{ response.body.company.name }}"
        }
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "create",
        "fields": {
          "name": "enriched",
          "status": "enriched",
          "note": "{{ note }}"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "call1"
    },
    {
      "id": "b",
      "from": "call1",
      "to": "m1"
    },
    {
      "id": "c",
      "from": "m1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-approval-routing-{{stamp}}",
  "description": "Branch on a record state and raise an approval task down the matching path.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "r1",
      "type": "openregister.object-read",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "filters": {
          "status": "reviewed"
        },
        "limit": 5,
        "fanOut": true
      }
    },
    {
      "id": "sw1",
      "type": "openregister.switch",
      "config": {}
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "create",
        "fields": {
          "name": "approval-task",
          "status": "awaiting-approval"
        }
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "r1"
    },
    {
      "id": "b",
      "from": "r1",
      "to": "sw1"
    },
    {
      "id": "c",
      "from": "sw1",
      "to": "w1"
    },
    {
      "id": "d",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-retention-sweep-{{stamp}}",
  "description": "Delete records that are past their keep-by state.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "r1",
      "type": "openregister.object-read",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "filters": {
          "status": "flagged"
        },
        "limit": 100,
        "fanOut": true
      }
    },
    {
      "id": "w1",
      "type": "openregister.object-write",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "operation": "delete",
        "match": [
          {
            "property": "sourceId",
            "value": "{{ sourceId }}"
          },
          {
            "property": "status",
            "value": "flagged"
          }
        ],
        "confirmDelete": true
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "r1"
    },
    {
      "id": "b",
      "from": "r1",
      "to": "w1"
    },
    {
      "id": "c",
      "from": "w1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-paginated-sync-{{stamp}}",
  "description": "Loops pages of an external API and hands each page to a sync sub-flow, upserting so a re-run converges.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "pages1",
      "type": "openregister.iterate",
      "config": {
        "source": {
          "type": "openregister.sub-flow",
          "config": {
            "flowId": "{{pagerFlow}}",
            "wait": true
          }
        },
        "body": [
          {
            "type": "openregister.sub-flow",
            "config": {
              "flowId": "{{syncFlow}}",
              "wait": true
            }
          }
        ],
        "maxIterations": 15,
        "onLimit": "fail"
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "pages1"
    },
    {
      "id": "b",
      "from": "pages1",
      "to": "e1"
    }
  ]
}

{
  "name": "flow-engine-batch-export-{{stamp}}",
  "description": "Read local objects and POST them outward in fixed-size batches.",
  "app": "openregister",
  "enabled": true,
  "executionMode": "async",
  "nodes": [
    {
      "id": "t1",
      "type": "openregister.trigger-manual",
      "config": {}
    },
    {
      "id": "r1",
      "type": "openregister.object-read",
      "config": {
        "register": "{{register}}",
        "schema": "{{schema}}",
        "limit": 10,
        "fanOut": true
      }
    },
    {
      "id": "b1",
      "type": "openregister.batch",
      "config": {
        "batchSize": 5
      }
    },
    {
      "id": "call1",
      "type": "openconnector.source-call",
      "config": {
        "method": "POST",
        "source": "{{extSource}}",
        "endpoint": "/posts"
      }
    },
    {
      "id": "e1",
      "type": "openregister.end",
      "config": {}
    }
  ],
  "edges": [
    {
      "id": "a",
      "from": "t1",
      "to": "r1"
    },
    {
      "id": "b",
      "from": "r1",
      "to": "b1"
    },
    {
      "id": "c",
      "from": "b1",
      "to": "call1"
    },
    {
      "id": "d",
      "from": "call1",
      "to": "e1"
    }
  ]
}
